const payload = $input.first().json || {};
const studies = Array.isArray(payload.studies) ? payload.studies : [];
const leads = [];
for (const st of studies) {
  const p = st.protocolSection || {};
  const id = p.identificationModule || {};
  const status = p.statusModule || {};
  const sponsor = (p.sponsorCollaboratorsModule || {}).leadSponsor || {};
  const design = p.designModule || {};
  const contacts = p.contactsLocationsModule || {};
  const central = Array.isArray(contacts.centralContacts) ? contacts.centralContacts : [];
  const officials = Array.isArray(contacts.overallOfficials) ? contacts.overallOfficials : [];
  const locations = Array.isArray(contacts.locations) ? contacts.locations : [];
  const siteEmails = [];
  for (const loc of locations) {
    for (const c of (loc.contacts || [])) {
      if (c.email && !siteEmails.includes(c.email)) siteEmails.push(c.email);
    }
  }
  const centralEmails = central.map((c) => c.email).filter(Boolean);
  const primaryEmail = centralEmails[0] || siteEmails[0] || null;
  leads.push({
    json: {
      nctId: id.nctId,
      briefTitle: id.briefTitle,
      leadSponsorName: sponsor.name || null,
      leadSponsorClass: sponsor.class || null,
      overallStatus: status.overallStatus || null,
      phases: design.phases || [],
      enrollmentCount: design.enrollmentInfo?.count || null,
      primaryEmail,
      centralContacts: central,
      overallOfficials: officials,
      siteEmailCount: siteEmails.length,
      studyUrl: `https://clinicaltrials.gov/study/${id.nctId}`,
    },
  });
}
return leads.filter((l) => l.json.primaryEmail || l.json.centralContacts.length > 0);
